from pathlib import Path
import re

DATA=Path('data6_arshan.js')
DETAILS=Path('details.js')
GALLERY=Path('place-gallery.js')
INDEX=Path('index.html')

data=DATA.read_text(encoding='utf-8')
# upgrade Badary
pat15=r'\{"i":"arshan-15".*?\}(?=,\{"i":"arshan-16")'
new15='''{"i":"arshan-15","d":"arshan","n":"Обсерватории Бадары — по экскурсии","x":"Большие радиотелескопы и радиогелиограф в Тункинской долине — редкая научная локация, которую стоит посещать только по предварительно согласованной экскурсии.","c":["unusual","photo"],"v":"verified","s":false,"p":"https://iaaras.ru/education/excursion/","u":"https://iaaras.ru/dept/badary/","t":"Подтверждено","o":"Не планируем самостоятельный проход на территорию; экскурсию согласовываем заранее."}'''
data,n=re.subn(pat15,new15,data,count=1,flags=re.S)
if n!=1: raise RuntimeError('arshan-15 data replace failed')
# merge arshan-16 and remove arshan-17
pat16=r'\{"i":"arshan-16".*?\}(?=,\{"i":"arshan-17")'
new16='''{"i":"arshan-16","d":"arshan","n":"Термальные источники «Вышка» у Жемчуга","x":"Две термальные скважины с разным составом и температурой воды в местности Вышка, в 1,5 км от Жемчуга.","c":["rest","unusual"],"v":"verified","s":false,"p":"https://tunkapark.ru/objects/mineralnyj-istochnik-vyshka","u":"https://tunkapark.ru/objects/mineralnyj-istochnik-vyshka","t":"Подтверждено","o":"Требуется разрешение на посещение нацпарка; режим доступности проверяем перед поездкой."}'''
data,n=re.subn(pat16,new16,data,count=1,flags=re.S)
if n!=1: raise RuntimeError('arshan-16 data replace failed')
data,n=re.subn(r',\{"i":"arshan-17".*?\}(?=,\{"i":"arshan-18")','',data,count=1,flags=re.S)
if n!=1: raise RuntimeError('arshan-17 data remove failed')
# remove separate Koymor lakes card; official viewpoint remains arshan-14
data,n=re.subn(r',\{"i":"arshan-19".*?\}(?=,\{"i":"arshan-20")','',data,count=1,flags=re.S)
if n!=1: raise RuntimeError('arshan-19 data remove failed')
DATA.write_text(data,encoding='utf-8')

cards={
'arshan-15':"""window.PLACE_DETAILS['arshan-15']={intro:'Научный комплекс в урочище Бадары с крупными радиотелескопами и многоволновым радиогелиографом — одна из самых необычных локаций Тункинской долины.',short:'Настоящие действующие обсерватории и гигантские радиоантенны — посещение только по заранее согласованной экскурсии.',why:'Бадары интересны именно тем, что это не декоративный туристический объект, а работающий научный комплекс. Здесь находятся радиоастрономические инструменты нескольких институтов РАН, поэтому правильный формат знакомства — организованная экскурсия, а не самостоятельная попытка попасть на территорию.',facts:['🔭 Радиоастрономическая обсерватория «Бадары» ИПА РАН работает с 2005 года','📡 На территории научного кластера находятся крупные радиотелескопы и многоволновый радиогелиограф','📞 ИПА РАН официально публикует отдельные телефон и e-mail для экскурсий в обсерваторию Бадары','👥 Действующие научно-популярные организаторы проводят экскурсии по обсерваториям Тункинской долины'],time:'Закладываем время только после подтверждения конкретной экскурсионной программы; обычно это не короткая дорожная остановка.',walk:'По территории — в составе экскурсионной группы. Самостоятельный проход не планируем.',access:'Урочище Бадары находится в Тункинском районе. Точный порядок заезда и место встречи получаем у организатора экскурсии; самостоятельно искать въезд на закрытую научную территорию не нужно.',parking:'Парковку и точку сбора считаем подтверждёнными только после получения инструкции от организатора конкретной экскурсии.',best:'Если хотим включить Бадары в поездку, бронируем заранее. Спонтанно ехать к воротам ради фотографий не стоит.',photo:['Большие антенны и радиотелескопы — только там, где разрешает сопровождающий','Многоволновый радиогелиограф','Панорама научного комплекса на фоне Саян'],nearby:['arshan-14','arshan-18'],amenities:'На территории это действующая научная инфраструктура, не обычный туристический парк. Бытовые условия уточняем при бронировании экскурсии.',fit:'✅ Да, но только как заранее организованная экскурсия. Для спонтанной остановки по дороге — нет.',important:'Не заходим на научную территорию самостоятельно и не запускаем дроны без отдельного разрешения. Перед поездкой подтверждаем дату, время, точку встречи и правила съёмки.',check:'Существование и оборудование обсерватории подтверждены официальным сайтом ИПА РАН. Возможность экскурсий подтверждена официальной страницей института с контактами, а также действующими организаторами научно-популярных экскурсий по Бадарам.'};""",
'arshan-16':"""window.PLACE_DETAILS['arshan-16']={intro:'Две термальные скважины в местности Вышка рядом с селом Жемчуг — короткая остановка с возможностью искупаться в минеральной воде.',short:'Термальные бассейны и две разные по составу скважины в 1,5 км от Жемчуга.',why:'Вышка удобна как расслабляющая остановка после природных и культурных точек Тункинской долины. Главное здесь не искать две разные достопримечательности: официальный нацпарк описывает единое месторождение с двумя скважинами примерно в 200 метрах друг от друга.',facts:['♨️ На Вышке две термальные скважины на расстоянии около 200 м','🌡 Одна из скважин имеет температуру воды около 38 °C и метановый состав','🧪 Месторождение сочетает метановые и углекислые термальные воды','📍 Источник расположен примерно в 1,5 км от села Жемчуг и в 3 км от федеральной дороги Култук–Монды'],time:'Около 45–90 минут на остановку и купание, если оно нам нужно.',walk:'Пешая часть минимальная, в пределах территории источников.',access:'С федеральной дороги Култук–Монды сворачиваем в сторону села Жемчуг и местности Вышка. Национальный парк прямо включает источник в свои автомобильные экскурсионные маршруты.',parking:'Точную схему парковки заранее не фиксируем; используем обозначенную площадку у туристической инфраструктуры Вышки.',best:'Удобно ставить ближе к концу дня как спокойную остановку. В выходные и хороший летний день людей может быть больше.',photo:['Термальный бассейн','Источник и курортная инфраструктура Вышки','Открытый пейзаж Тункинской долины вокруг Жемчуга'],nearby:['arshan-14','arshan-15'],amenities:'На Вышке есть туристическая инфраструктура и визит-центр «Жемчужина». Билет на посещение термальных источников можно купить в кассе на месте.',fit:'✅ Да. Автомобильный подъезд и минимальная пешая часть хорошо подходят нашему формату.',important:'Для посещения объектов национального парка нужно разрешение. При действующем особом противопожарном режиме перед выездом обязательно проверяем доступность по актуальной карте парка. Минеральную воду не воспринимаем как универсальное лечение; при медицинских противопоказаниях ориентируемся на врача.',check:'Расположение, две скважины, их различия, автомобильный экскурсионный маршрут и возможность покупки билета подтверждены официальным сайтом Тункинского национального парка.'};"""
}
text=DETAILS.read_text(encoding='utf-8')
for key in ['arshan-15','arshan-16','arshan-17','arshan-19']:
    text=re.sub(r"window\.PLACE_DETAILS\['"+key+r"'\]=\{.*?\};\s*",'',text,flags=re.S)
for key in ['arshan-15','arshan-16']:
    text=text.rstrip()+'\n'+cards[key]+'\n'
# remove obsolete nearby refs cleanly from common array forms
text=text.replace(",'arshan-17'",'').replace("'arshan-17',",'').replace(",'arshan-19'",'').replace("'arshan-19',",'')
DETAILS.write_text(text,encoding='utf-8')

# remove obsolete galleries if they exist; keep current arshan-16 gallery
if GALLERY.exists():
    g=GALLERY.read_text(encoding='utf-8')
    for key in ['arshan-17','arshan-19']:
        g=re.sub(r'Object\.assign\(window\.GALLERIES,\{"'+key+r'":\[.*?\]\}\);\s*','',g,flags=re.S)
    GALLERY.write_text(g,encoding='utf-8')

idx=INDEX.read_text(encoding='utf-8')
if 'details.js?build=14' not in idx: raise RuntimeError('details build 14 not found')
idx=idx.replace('details.js?build=14','details.js?build=15',1)
if '<script src="data6_arshan.js"></script>' in idx:
    idx=idx.replace('<script src="data6_arshan.js"></script>','<script src="data6_arshan.js?build=1"></script>',1)
INDEX.write_text(idx,encoding='utf-8')

final_data=DATA.read_text(encoding='utf-8')
final_details=DETAILS.read_text(encoding='utf-8')
assert final_data.count('"i":"arshan-15"')==1
assert final_data.count('"i":"arshan-16"')==1
assert '"i":"arshan-17"' not in final_data
assert '"i":"arshan-19"' not in final_data
assert final_details.count("window.PLACE_DETAILS['arshan-15']=")==1
assert final_details.count("window.PLACE_DETAILS['arshan-16']=")==1
assert "window.PLACE_DETAILS['arshan-17']=" not in final_details
assert "window.PLACE_DETAILS['arshan-19']=" not in final_details
assert "'arshan-17'" not in final_details
assert "'arshan-19'" not in final_details
print('Badary upgraded; Vyshka merged; duplicate arshan-17 and separate arshan-19 removed')
